// FEATURE 3 - Batch Forgery Detector / handwriting similarity (SIMULATED).
// No OCR engine and no trained Siamese Neural Network are integrated in this prototype.
// Each synthetic document carries a 24-dimensional "embedding" generated by the seed script, and similarity is the
// cosine between two embeddings - the same comparison step a Siamese network would perform on learned embeddings.
// A similarity value is NOT proof of forgery or common authorship.
import { hashStr, mulberry32, gauss } from './rng.js'

export const EMBED_DIM = 24

export function cosine(a, b) {
  let dot = 0
  let na = 0
  let nb = 0
  for (let i = 0; i < a.length; i++) {
    dot += a[i] * b[i]
    na += a[i] * a[i]
    nb += b[i] * b[i]
  }
  return na && nb ? dot / Math.sqrt(na * nb) : 0
}

// Embedding for a newly uploaded file in the prototype: derived from the file name/size ONLY (not from the image).
export function simulatedEmbeddingFromFile(name, size) {
  const r = mulberry32(hashStr(`${name}:${size}`))
  return Array.from({ length: EMBED_DIM }, () => +gauss(r).toFixed(3))
}

// Pairwise comparison across all documents. Returns pairs >= threshold and union-find groups.
export function compareDocuments(apps, threshold) {
  const docs = apps.filter((a) => a.document && a.document.embedding)
  const pairs = []
  for (let i = 0; i < docs.length; i++) {
    for (let j = i + 1; j < docs.length; j++) {
      const sim = cosine(docs[i].document.embedding, docs[j].document.embedding)
      if (sim >= threshold) {
        const lowQ = Math.min(docs[i].document.scanQuality, docs[j].document.scanQuality) < 0.5
        pairs.push({ a: docs[i].id, b: docs[j].id, sim: +sim.toFixed(3), lowQuality: lowQ })
      }
    }
  }
  pairs.sort((x, y) => y.sim - x.sim)
  const parent = {}
  const find = (x) => (parent[x] === undefined || parent[x] === x ? (parent[x] = x) : (parent[x] = find(parent[x])))
  pairs.forEach((p) => {
    parent[find(p.a)] = find(p.b)
  })
  const groupsMap = {}
  Object.keys(parent).forEach((id) => {
    const root = find(id)
    ;(groupsMap[root] = groupsMap[root] || []).push(id)
  })
  const groups = Object.values(groupsMap)
    .filter((g) => g.length > 1)
    .sort((x, y) => y.length - x.length)
    .map((ids, i) => ({ id: `HW-${i + 1}`, ids: ids.sort() }))
  return { pairs, groups }
}

